.sky {
  width: 520px;
  height: 300px;
  margin: 24px;
}

.tower {
  background-color: #1e293b;
}

/* ---- Solution ---- */
.sky {
  position: relative;
  display: flex;
  align-items: flex-end;
  overflow: hidden;
  border-radius: 16px;
  background-image: linear-gradient(#0f172a, #312e81 70%, #7c3aed);
}

.moon {
  position: absolute;
  top: 28px;
  right: 40px;
  width: 56px;
  height: 56px;
  border-radius: 50%;
  box-shadow: inset -14px 8px 0 #fde68a;
}

.city {
  display: flex;
  flex: 1;
  align-items: flex-end;
  gap: 6px;
  padding: 0 16px;
}

.tower {
  flex: 1;
  background-image:
    repeating-linear-gradient(90deg, #1e293b 0 8px, transparent 8px 14px),
    repeating-linear-gradient(#1e293b 0 10px, #fde68a 10px 16px);
}

.t1 {
  height: 120px;
}

.t2 {
  flex: 1.4;
  height: 190px;
}

.t3 {
  height: 150px;
}

.t4 {
  height: 230px;
  border-radius: 6px 6px 0 0;
}

.t5 {
  height: 100px;
}
